import Foundation

/// Verify the exact URL generated by the UI test after the main app relaunch,
/// then acknowledge only this fixture through the production locked store.
@main
struct VerifyInbox {
  static func main() throws {
    guard CommandLine.arguments.count == 4 else {
      throw SharedTextStore.Failure("Usage: verify-inbox <group-directory> <test-log> <fixture-container>")
    }
    let group = URL(fileURLWithPath: CommandLine.arguments[1])
    let log = try String(contentsOfFile: CommandLine.arguments[2], encoding: .utf8)
    let pattern = #"(?m)^SHARE_FIXTURE_URL=(http://127\.0\.0\.1:8765/#gemsnote-ui-[0-9a-f-]{36})$"#
    let expression = try NSRegularExpression(pattern: pattern)
    guard let match = expression.firstMatch(in: log, range: NSRange(log.startIndex..., in: log)),
      let range = Range(match.range(at: 1), in: log) else {
      throw SharedTextStore.Failure("Missing exact test URL")
    }
    let expected = String(log[range])
    let directory = group.appendingPathComponent("SharedTextInbox")
    let queue = directory.appendingPathComponent("queue.json")
    let records = try JSONDecoder().decode([SharedTextRecord].self, from: Data(contentsOf: queue))
    let matches = records.filter { $0.text == expected }
    guard matches.count == 1, let record = matches.first,
      record.accountKey.isEmpty, record.resourceKind == nil else {
      throw SharedTextStore.Failure("Expected exactly one unclaimed URL in the real App Group inbox")
    }
    try record.validate()
    let batchExpression = try NSRegularExpression(pattern: #"(?m)^SHARE_BATCH_ID=([0-9a-f-]{36})$"#)
    guard let batchMatch = batchExpression.firstMatch(in: log, range: NSRange(log.startIndex..., in: log)),
      let batchRange = Range(batchMatch.range(at: 1), in: log) else {
      throw SharedTextStore.Failure("Missing batch fixture ID")
    }
    let batchID = String(log[batchRange])
    let originalDirectory = URL(fileURLWithPath: CommandLine.arguments[3])
      .appendingPathComponent("tmp").appendingPathComponent(batchID)
    var verified = [record]
    for (suffix, kind) in [("png", "image"), ("bin", "attachment"), ("gif", "attachment")] {
      let name = "gemsnote-\(batchID).\(suffix)"
      let candidates = records.filter { $0.resourceName == name }
      guard candidates.count == 1, let resource = candidates.first,
        resource.accountKey.isEmpty, resource.resourceKind == kind else {
        throw SharedTextStore.Failure("Expected exactly one unclaimed \(kind): \(name)")
      }
      try resource.validate()
      let original = try Data(contentsOf: originalDirectory.appendingPathComponent(name))
      let saved = try Data(contentsOf: directory.appendingPathComponent(resource.id + ".resource"))
      guard original == saved, saved.count == resource.resourceSize else {
        throw SharedTextStore.Failure("Shared bytes differ from original: \(name)")
      }
      verified.append(resource)
    }
    let expectedText = "Shared text file \(batchID)\n正文"
    let textMatches = records.filter { $0.text == expectedText }
    guard textMatches.count == 1, let textRecord = textMatches.first,
      textRecord.accountKey.isEmpty, textRecord.resourceKind == nil else {
      throw SharedTextStore.Failure("Text file must be imported as complete text, not an attachment")
    }
    verified.append(textRecord)
    let invalidExpression = try NSRegularExpression(pattern: #"(?m)^SHARE_INVALID_ID=([0-9a-f-]{36})$"#)
    guard let invalidMatch = invalidExpression.firstMatch(in: log, range: NSRange(log.startIndex..., in: log)),
      let invalidRange = Range(invalidMatch.range(at: 1), in: log) else {
      throw SharedTextStore.Failure("Missing invalid batch fixture ID")
    }
    let invalidID = String(log[invalidRange])
    guard !records.contains(where: { ($0.resourceName ?? "").contains(invalidID) || $0.text.contains(invalidID) }) else {
      throw SharedTextStore.Failure("Failed batch partially persisted")
    }
    let invalidDirectory = URL(fileURLWithPath: CommandLine.arguments[3])
      .appendingPathComponent("tmp").appendingPathComponent(invalidID)
    let store = SharedTextStore(directory: directory)
    let languageExpression = try NSRegularExpression(pattern: #"(?m)^SHARE_LANGUAGE_ID=([0-9a-f-]{36})$"#)
    let languageMatches = languageExpression.matches(in: log, range: NSRange(log.startIndex..., in: log))
    guard languageMatches.count == 3 else {
      throw SharedTextStore.Failure("Missing three cross-process language checks")
    }
    for match in languageMatches {
      guard let range = Range(match.range(at: 1), in: log) else {
        throw SharedTextStore.Failure("Invalid language fixture ID")
      }
      let id = String(log[range])
      guard !records.contains(where: { ($0.resourceName ?? "").contains(id) || $0.text.contains(id) }) else {
        throw SharedTextStore.Failure("Cancelled language check persisted a record")
      }
      let files = URL(fileURLWithPath: CommandLine.arguments[3])
        .appendingPathComponent("tmp").appendingPathComponent(id)
      try FileManager.default.removeItem(at: files)
    }
    for fixture in verified { try store.acknowledge(id: fixture.id) }
    try FileManager.default.removeItem(at: originalDirectory)
    try FileManager.default.removeItem(at: invalidDirectory)
    print("PASS URL and text file decoded, PNG/binary/GIF originals preserved; invalid batch absent; removed only five fixture records")
  }
}
